import{_ as r,a0 as a,w as d,s as m,ao as i,I as n,x as p,a1 as o,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"命令行星期二——第四部分 | LCTT x X-CMD","titleTemplate":false,"description":"命令行星期二——第四部分 | LCTT (201407) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"命令行星期二——第四部分 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"命令行星期二——第四部分 | LCTT (201407) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201407/20140709 Command Line Tuesdays--Part Four","title":"命令行星期二——第四部分","tag":"201407","desc":""},"relativePath":"201407/20140709 Command Line Tuesdays--Part Four.md","filePath":"[post].md"}'),l={name:"201407/20140709 Command Line Tuesdays--Part Four.md"};function u(f,e,c,T,g,C){const t=a("Link");return d(),m("div",null,[e[11]||(e[11]=i('<h1 id="命令行星期二——第四部分" tabindex="-1">命令行星期二——第四部分 <a class="header-anchor" href="#命令行星期二——第四部分" aria-label="Permalink to “命令行星期二——第四部分”">​</a></h1><p>大家好。新的一周，新的冒险！</p><p>今天，我们将会学习使用四个相当简单的命令去操作文件。好，废话少说，我们开始吧。</p><p>在开始学习这些命令之前，我们先稍微说些题外话，讲讲“通配符”的用处。</p><p>###通配符###</p><p>使用图形工具区复制、粘贴、新建目录等操作也许很容易，但是若想完成一些更复杂的任务，例如仅仅将一个目录下的所有.html文件复制到另一个目录中、或者只复制在某个目录中不存在的文件，这时命令行也许会比较方便。我们回到通配符的学习中，通配符是shell的基本功能，它是一个由一些特殊字符组成的集合，它让你可以用一些简单的规则来选择出某些文件。（通配符可以出现在文件名中，用于指定文件名的字符个数和字母的大/小写等规则）。</p><p>如下表 ：</p><p><img src="https://news.opensuse.org/wp-content/uploads/2014/07/Screenshot-08.-07.-2014-125946.png" alt=""></p><p>下面是肖茨先生给出的一些实例，如下表：</p><p><img src="https://news.opensuse.org/wp-content/uploads/2014/07/Screenshot-08.-07.-2014-125959.png" alt=""></p><p>如果你使用一个包含文件名参数的命令，你就可以使用通配符。</p><p>###cp###</p><p>cp是一个用于复制文件或者目录的命令，它的用法相当的简单。进入到你想复制的文件所在的目录，然后使用如下命令</p><p><code>cp file1 file2</code> -复制一个文件</p><p>或者</p><p><code>cp file1 file2 ... directory</code> -从当前工作目录复制多个文件到指定的目录。</p><p>下表是肖茨先生给出的cp命令的一些选项：</p><p><img src="https://news.opensuse.org/wp-content/uploads/2014/07/Screenshot-08.-07.-2014-134248.png" alt=""></p><p>###mv###</p><p>mv是今天的第二个命令，我们可以使用mv来重命名一个文件或目录，或者移动一个文件或目录。我们可以这样使用mv命令。</p><p><code>mv filename1 filename2</code> -若想将文件filename1重命名为filename2。</p><p>或者</p><p><code>mv file directory</code> -若想将一个文件移动到某个目录。</p><p>下表是一些mv命令的实例</p><p><img src="https://news.opensuse.org/wp-content/uploads/2014/07/Screenshot-08.-07.-2014-133515.png" alt=""></p><p>###rm###</p><p>rm命令是用于删除文件或目录，它的用法比较直接，如下：</p><p><code>rm file</code></p><p>或者</p><p><code>rm -r driectory</code></p><p>这里也有一个包含rm其他选项的表</p><p><img src="https://news.opensuse.org/wp-content/uploads/2014/07/Screenshot-08.-07.-2014-133529.png" alt=""></p><p>但是，使用rm命令时要小心点。因为并没有撤销删除的选项，因此使用rm命令式要格外的小心，避免对你的系统造成不必要的破坏。</p><p>###mkdir###</p><p>mkdir是用于创建目录.它是今天最简单的一个命令：</p><p><code>mkdir directory</code></p><p>看，目录成功创建了！</p><p>这是本周的内容，下周二再见，致以最真诚的问候！</p><hr>',39)),n("p",null,[e[1]||(e[1]=p("via: ",-1)),o(t,{href:"https://news.opensuse.org/2014/07/08/command-line-tuesdays-part-four/"},{default:s(()=>[...e[0]||(e[0]=[p("https://news.opensuse.org/2014/07/08/command-line-tuesdays-part-four/",-1)])]),_:1})]),n("p",null,[e[4]||(e[4]=p("译者：",-1)),o(t,{href:"https://github.com/cvsher"},{default:s(()=>[...e[2]||(e[2]=[p("cvsher",-1)])]),_:1}),e[5]||(e[5]=p(" 校对：",-1)),o(t,{href:"https://github.com/wxy"},{default:s(()=>[...e[3]||(e[3]=[p("wxy",-1)])]),_:1})]),n("p",null,[e[8]||(e[8]=p("本文由 ",-1)),o(t,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[6]||(e[6]=[p("LCTT",-1)])]),_:1}),e[9]||(e[9]=p(" 原创翻译，",-1)),o(t,{href:"http://linux.cn/"},{default:s(()=>[...e[7]||(e[7]=[p("Linux中国",-1)])]),_:1}),e[10]||(e[10]=p(" 荣誉推出",-1))])])}const L=r(l,[["render",u]]);export{x as __pageData,L as default};
